    if (i == 0) {
        free(tmp);
        abort_flag = 1;
    }

    // if we received characters, store them in the array
    else {
        for (i = 0; i < ARRAY_SIZE; i++) {
            array[i] = tmp[i];
        }
    }

    // tidy up
	free(tmp);

    // if the abort flag is set, print the array
    if (abort_flag) {
        printf("%s\n", array);
    }

    return 0;
}

